insert into public.work_posts(id,leader_id,title,body,images,category,country) values('solar-future','elena-martinez','A brighter future, powered by the sun.','Today, we inaugurated the largest community solar initiative in Andalusia. 50,000 homes will now have access to clean, affordable energy — reducing household bills and our carbon footprint.
insert into public.work_posts(id,leader_id,title,body,images,category,country) values('healthcare-access','james-anderson','Quality healthcare, closer to home.','Our new rural healthcare program is now live in 24 communities. More family doctors, shorter wait times, and care where it matters most. This is what investing in people looks like.',array['/images/healthcare.svg'],'Health','Canada') on conflict(id) do nothing;
insert into public.work_posts(id,leader_id,title,body,images,category,country) values('classrooms-tomorrow','aiko-tanaka','Opening doors for the next generation.','Every child deserves the tools to dream bigger. This week, 120 public schools received new digital learning labs, training for teachers, and expanded scholarship support.',array['/images/education.svg'],'Education','Japan') on conflict(id) do nothing;
insert into public.work_posts(id,leader_id,title,body,images,category,country) values('community-alexander-weber','alexander-weber','Investing in a cleaner tomorrow.','Today marks an important milestone in our national community investment program. Working alongside local teams, we are delivering lasting improvements in essential services. Explore the progress and share your perspective below.','{}','Environment','Germany') on conflict(id) do nothing;
